// Compile-time contract check: every zod schema the client validates responses with must match
// the backend's OpenAPI schema (`openapi.ts`, generated by `npm run gen:api`). A drift is a
// `tsc` error here. Nothing in this file runs.
import type { z } from "zod";
import type { components } from "./openapi";
import type * as A from "./analysis";
import type * as Api from "./api";

type S = components["schemas"];
type Same<Keys1, Keys2> = [Exclude<Keys1, Keys2> | Exclude<Keys2, Keys1>] extends [never]
  ? true
  : { missingOrExtra: Exclude<Keys1, Keys2> | Exclude<Keys2, Keys1> };
/** The API's response type parses as the zod type, and both declare the same fields. */
type Conforms<Gen, Zod> = [Gen] extends [Zod] ? Same<keyof Gen, keyof Zod> : { notAssignable: Gen };
type Check<T extends true> = T;
// z.input: fields with a zod `.default()` are optional on the wire.
type Z<T extends z.ZodTypeAny> = z.input<T>;

export type Contract = [
  Check<Conforms<S["UserOut"], Z<typeof Api.userSchema>>>,
  Check<Conforms<S["TokenOut"], Z<typeof Api.tokenSchema>>>,
  Check<Conforms<S["JobOut"], Z<typeof Api.jobSchema>>>,
  Check<Conforms<S["AnalysisBrief"], Z<typeof Api.analysisBriefSchema>>>,
  Check<Conforms<S["EvidenceOut"], Z<typeof Api.evidenceSchema>>>,
  Check<Conforms<S["VideoOut"], Z<typeof Api.videoSchema>>>,
  Check<Conforms<S["ReviewOut"], Z<typeof Api.reviewSchema>>>,
  Check<Conforms<S["UploadOut"], Z<typeof Api.uploadSchema>>>,
  Check<Conforms<S["StationOut"], Z<typeof Api.stationSchema>>>,
  Check<Conforms<S["RubricOut"], Z<typeof Api.rubricSchema>>>,
  Check<Conforms<S["ReportGroup"], Z<typeof Api.reportGroupSchema>>>,
  Check<Conforms<S["FailedCheck"], Z<typeof Api.failedCheckSchema>>>,
  Check<Conforms<S["ReportSummary"], Z<typeof Api.reportSummarySchema>>>,
  Check<Conforms<S["ApiKeyOut"], Z<typeof Api.apiKeySchema>>>,
  Check<Conforms<S["ApiKeyCreated"], Z<typeof Api.apiKeyCreatedSchema>>>,
  Check<Conforms<S["AuditLogOut"], Z<typeof Api.auditEntrySchema>>>,
  Check<Conforms<S["AnalysisResult"], Z<typeof A.analysisResultSchema>>>,
  Check<Conforms<S["StepResult"], Z<typeof A.stepSchema>>>,
  Check<Conforms<S["CheckResult"], Z<typeof A.checkSchema>>>,
  Check<Conforms<S["Barcode"], Z<typeof A.barcodeSchema>>>,
];
